import json,copy
from pathlib import Path
O=Path(__file__).parent;a=json.loads((O/'EJR_inventory.json').read_text());b=json.loads((O/'EJR_supplement-inventory.json').read_text());scan=json.loads((O/'EJR_exhaustive-blob-scan.json').read_text());selected={(r['workspace'],r['module']):copy.deepcopy(r) for r in a['selected']}
